    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    cnt = Counter(x for row in g for x in row)
    bg = cnt.most_common(1)[0][0]
    edge = Counter()
    for r in range(h):
        for c in range(w):
            if r in (0, h - 1) or c in (0, w - 1):
                if g[r][c] != bg:
                    edge[g[r][c]] += 1
    rail = edge.most_common(1)[0][0]
    cue = next(x for x in cnt if x not in (bg, rail))
    pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == cue]
    left = [r for r in range(h) if g[r][0] == rail]
    right = [r for r in range(h) if g[r][w - 1] == rail]
    if pts:
        r0, c0 = pts[0]
        # Ray from cue toward nearest vertical edge, with cue colored 4.
        if c0 <= w - 1 - c0:
            for c in range(1, c0):
                g[r0][c] = cue
        else:
