                g[r0][c] = cue
        # If two separate vertical rails form a corridor, extend a ray through
        # the gap from the side whose run does not contain the cue.
        if left and right and (r0 not in left or r0 not in right):
            pass
        g[r0][c0] = 4
        # Rails define parallel signal lines perpendicular to their axis.
        # Fill the axis line passing through the cue, bounded by grid edges.
        for r in range(1, h - 1):
            if r != r0 and g[r][c0] == bg:
                g[r][c0] = cue
    return g
