 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    from collections import Counter
    counts=Counter(v for row in g for v in row)
    bg=counts.most_common(1)[0][0]
    edge=Counter(g[r][c] for r in range(h) for c in range(w)
                 if (r in (0,h-1) or c in (0,w-1)) and g[r][c]!=bg)
    frame=edge.most_common(1)[0][0]
    accent=next(v for v in counts if v not in (bg,frame))
    # Each frame segment projects parallel rays inward from alternating
    # interior positions; isolated accent cells on a ray become 4 endpoints.
    def segments(vals):
        result=[]
        for v in vals:
            if not result or v>result[-1][-1]+1: result.append([v])
            else: result[-1].append(v)
        return result
    for c in (0,w-1):
        vals=[r for r in range(h) if g[r][c]==frame]
        for seg in segments(vals):
            for r in seg[1:-1:2]:
                for x in range(1,w-1): g[r][x]=accent
    for r in (0,h-1):
        vals=[c for c in range(w) if g[r][c]==frame]
        for seg in segments(vals):
            for c in seg[1:-1:2]:
                for y in range(1,h-1): g[y][c]=accent
    # A signal on a projected stripe marks its endpoint; otherwise connect it
    # back toward the closest matching frame rail on that axis.
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=accent: continue
            if g[r][c]==accent: # already belongs to a frame-projected line
                # Paint toward nearest border in the stripe's perpendicular axis.
                pass
            if c < w-1-c:
                for x in range(c+1,w-1): g[r][x]=accent
            else:
                for x in range(1,c): g[r][x]=accent
            g[r][c]=4
    return g
",
