 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    from collections import Counter
    counts=Counter(v for row in g for v in row)
    bg=counts.most_common(1)[0][0]
    edge_counts=Counter(g[r][c] for r in range(h) for c in range(w)
        if (r in (0,h-1) or c in (0,w-1)) and g[r][c]!=bg)
    frame=edge_counts.most_common(1)[0][0]
    accent=next(v for v in counts if v not in (bg,frame))
    # Mark each frame segment's center-directed perpendicular ray, then extend
    # the isolated cue along its column until it meets the lower frame band.
    left=[r for r in range(h) if g[r][0]==frame]
    right=[r for r in range(h) if g[r][w-1]==frame]
    def runs(xs):
        out=[]
        for x in xs:
            if not out or x>out[-1][-1]+1: out.append([x])
            else: out[-1].append(x)
        return out
    for side in (0,w-1):
        vals=[r for r in range(h) if g[r][side]==frame]
        for seg in runs(vals):
            # Frame run projects inward from its central rows.
            centers=[seg[(len(seg)-1)//2]] if len(seg)%2 else [seg[len(seg)//2-1],seg[len(seg)//2]]
            for rr in centers:
                for cc in range(1,w-1): g[rr][cc]=accent
    for r in range(h):
        for c in range(w):
            if grid[r][c]==accent:
                # Seed color ray extends toward the bottom edge; seed is 4.
                for rr in range(r+1,h-1): g[rr][c]=accent
                g[r][c]=4
    return g
