 "content": "def transform(grid):
    """Project each boundary rail inward and connect interior cues to rails."""
    from collections import Counter

    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]

    # The rail is the non-background color most frequently found on the edge.
    edge_counts = Counter(
        g[r][c]
        for r in range(h)
        for c in range(w)
        if (r in (0, h - 1) or c in (0, w - 1)) and g[r][c] != bg
    )
    rail = edge_counts.most_common(1)[0][0]
    cue_colors = [v for v in counts if v not in (bg, rail)]
    if not cue_colors:
        return g
    cue = cue_colors[0]
    seeds = [(r, c) for r in range(h) for c in range(w) if g[r][c] == cue]

    def runs(coords):
        result = []
        for x in coords:
            if not result or x > result[-1][-1] + 1:
                result.append([x])
            else:
                result[-1].append(x)
        return result

    # Each contiguous rail segment emits a perpendicular ray through its
    # rounded-up midpoint. Rays stop at a cue, which is changed to 4.
    rays = []
    for r in (0, h - 1):
        cols = [c for c in range(w) if g[r][c] == rail]
        for seg in runs(cols):
            center = (seg[0] + seg[-1] + 1) // 2
            dr = 1 if r == 0 else -1
            rays.append((r, center, dr, 0))
    for c in (0, w - 1):
        rows = [r for r in range(h) if g[r][c] == rail]
        for seg in runs(rows):
            center = (seg[0] + seg[-1] + 1) // 2
            dc = 1 if c == 0 else -1
            rays.append((center, c, 0, dc))

    for r, c, dr, dc in rays:
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if (rr, cc) in seeds:
                g[rr][cc] = 4
                break
            if g[rr][cc] == bg:
                g[rr][cc] = cue
            rr += dr
            cc += dc

    # Every cue connects along its row or column to the nearest rail cell.
    # This naturally handles a cue lying on a rail's projected centerline.
    for r, c in seeds:
        candidates = []
