 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]
    edge = Counter(g[r][c] for r in range(h) for c in range(w)
                   if (r in (0, h - 1) or c in (0, w - 1)) and g[r][c] != bg)
    frame = edge.most_common(1)[0][0]
    accent = next(x for x in counts if x not in (bg, frame))

    # Interior signal extends to the right-hand frame and becomes the 4 marker.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == accent:
                g[r][c] = 4
                for x in range(c + 1, w - 1):
                    g[r][x] = accent

    # Each vertical frame run projects an accent-colored ray from its inward
    # terminal row; preserve the frame cells at the borders.
    for col in (0, w - 1):
        rows = [r for r in range(h) if grid[r][col] == frame]
        runs = []
        for r in rows:
            if not runs or r != runs[-1][-1] + 1:
                runs.append([r])
            else:
                runs[-1].append(r)
        for run in runs:
            r = run[-1]
            for c in range(1, w - 1):
                g[r][c] = accent
    return g
